<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Exercise; use App\Services\StatisticsService; use Illuminate\Http\Request;
class StatisticsController extends Controller { public function __construct(private StatisticsService $stats){} public function summary(Request $r){$d=$r->validate(['preset'=>'nullable|in:week,month,last10,last30,custom','from'=>'required_if:preset,custom|nullable|date','to'=>'required_if:preset,custom|nullable|date|after_or_equal:from']);[$f,$t]=$this->stats->range($d['preset']??'last30',$d['from']??null,$d['to']??null,$r->user()->timezone);return ['data'=>$this->stats->summary($r->user()->id,$f,$t)];} public function exercise(Request $r,Exercise $exercise){abort_unless($exercise->user_id===null||$exercise->user_id===$r->user()->id,404);$d=$r->validate(['preset'=>'nullable|in:week,month,last10,last30,custom','from'=>'nullable|date','to'=>'nullable|date']);[$f,$t]=$this->stats->range($d['preset']??'last30',$d['from']??null,$d['to']??null,$r->user()->timezone);return ['data'=>$this->stats->exerciseProgress($r->user()->id,$exercise->id,$f,$t)];} }
